/// Writes the C# files, as text a developer can read.
module Plasm.Seam.Emit

open System
open System.Text
open System.Text.RegularExpressions
open Microsoft.CodeAnalysis.CSharp

let private header =
    """// <auto-generated>
//   Written by Plasm.Seam from the F# data assembly and Seam.cs. Do not edit:
//   change the F# types or Seam.cs and build again. seam.lock describes the contract.
// </auto-generated>
#nullable enable

"""

let private known =
    Regex
        @"global::System\.Threading\.Tasks\.|global::System\.Threading\.|global::System\.Collections\.Generic\.|global::Plasm\.CSharp\.|global::Microsoft\.FSharp\.Core\.|global::Microsoft\.FSharp\.Collections\.|global::System\.(?=[A-Z]\w*(?![\w.]))"

/// Shorter names for what the usings at the top of each file bring in.
let short (cs: string) = known.Replace(cs, "")

let private start (seam: SeamModel) (usings: string list) =
    let text = StringBuilder(header)

    for u in usings |> List.sortWith (fun a b -> String.CompareOrdinal(a, b)) do
        text.Append($"using {u};\n") |> ignore

    text.Append($"\nnamespace {seam.Namespace};\n").ToString()

let private id' (name: string) =
    if SyntaxFacts.GetKeywordKind name <> SyntaxKind.None then "@" + name else name

let private parameters (all: string list) (indent: string) =
    let line = String.concat ", " all

    if line.Length <= 100 then
        line
    else
        "\n" + (all |> List.map (fun p -> indent + "    " + p) |> String.concat ",\n")

/// The F# doc comment's summary for `id`, as a C# one, or `fallback`.
let private summary (seam: SeamModel) (line: string -> unit) (indent: string) (id: string) (fallback: string list) =
    match seam.Docs.TryGetValue id with
    | true, text -> line $"{indent}/// <summary>{text}</summary>"
    | _ ->
        for f in fallback do
            line $"{indent}/// {f}"

/// Each field's F# doc comment, as the C# record's parameter's.
let private paramDocs (seam: SeamModel) (line: string -> unit) (owner: string) (fields: Field seq) =
    for f in fields do
        match seam.Docs.TryGetValue $"P:{owner}.{f.Member}" with
        | true, text -> line $"/// <param name=\"{f.Name}\">{text}</param>"
        | _ -> ()

/// A member's doc id: by its name, and the number of its parameters.
let private memberDoc (seam: SeamModel) (owner: string) (m: Member) =
    if m.Property then
        $"P:{owner}.{m.Name}"
    else
        let bare = $"M:{owner}.{m.Name}"

        let count (id: string) =
            if not (id.Contains '(') then
                0
            else
                let inside = id.Substring(id.IndexOf '(' + 1).TrimEnd(')')
                let mutable depth = 0
                let mutable commas = 0

                for ch in inside do
                    match ch with
                    | '{' -> depth <- depth + 1
                    | '}' -> depth <- depth - 1
                    | ',' when depth = 0 -> commas <- commas + 1
                    | _ -> ()

                commas + 1

        match
            seam.Docs.Keys
            |> Seq.filter (fun k -> (k = bare || k.StartsWith(bare + "(")) && count k = m.Parameters.Length)
            |> List.ofSeq
        with
        | [ one ] -> one
        | _ -> ""

let private fieldList (fields: Field seq) =
    fields |> Seq.map (fun f -> $"{f.Cross.CsFull} {id' f.Name}") |> List.ofSeq

// ---- the views ----

let private viewsFile (seam: SeamModel) =
    let text = StringBuilder(start seam [ "System"; "System.Text.Json.Serialization"; "Plasm.CSharp" ])
    let line (s: string) = text.Append(s).Append('\n') |> ignore

    for r in seam.Records do
        line ""
        summary seam line "" $"T:{r.Display}" [ $"{r.Display}, as C# sees it." ]
        paramDocs seam line r.Display r.Fields
        line $"public sealed record {r.Name}({parameters (fieldList r.Fields) String.Empty});"

    for u in seam.Unions do
        for c in u.Cases do
            line ""
            summary seam line "" $"T:{u.Display}.{c.Case}" [ $"A case of {u.Name}." ]
            let fields = if c.Fields.Count = 0 then "" else $"({parameters (fieldList c.Fields) String.Empty})"
            line $"public sealed record {c.Name}{fields}"
            line "{"
            line $"    [JsonPropertyOrder(-1)] public string Kind => \"{c.Kind}\";"
            line "}"

        line ""
        summary seam line "" $"T:{u.Display}" [ $"{u.Display}, as C# sees it: a switch over it that misses a case does not compile." ]
        line $"[JsonUnion(TypeClassifier = typeof({u.Name}ByKind))]"
        line $"""public union {u.Name}({u.Cases |> Seq.map _.Name |> String.concat ", "});"""
        line ""
        line $"/// Which case of {u.Name} a JSON object is, by its \"kind\"."
        line $"public sealed class {u.Name}ByKind() : ByKind(typeof({u.Name}),"
        line "["

        for c in u.Cases do
            line $"    Tuple.Create(\"{c.Kind}\", typeof({c.Name})),"

        line "]);"

    short (text.ToString())

// ---- the mapping ----

let private mapFile (seam: SeamModel) =
    let text =
        StringBuilder(
            start seam [ "System"; "System.Collections.Generic"; "Microsoft.FSharp.Collections"; "Microsoft.FSharp.Core"; "Plasm.CSharp" ]
        )

    let line (s: string) = text.Append(s).Append('\n') |> ignore

    line
        """
/// Each domain value as its view.
public static class SeamMap
{
    /// Every item of `items`, each as `view` makes it.
    public static TOut[] Each<TIn, TOut>(IEnumerable<TIn> items, Func<TIn, TOut> view)
    {
        var list = new List<TOut>();
        foreach (var item in items) list.Add(view(item));
        return list.ToArray();
    }"""

    for r in seam.Records do
        line ""
        line $"    public static {r.Name} View(this {r.Domain} value) => new("

        line (
            (r.Fields
             |> Seq.map (fun f -> $"""        {id' f.Name}: {f.Cross.Out($"value.{id' f.Member}")}""")
             |> String.concat ",\n")
            + ");"
        )

        match r.Into with
        | Some fields ->
            line ""
            line $"    public static {r.Domain} Domain(this {r.Name} value) => new("
            line ((fields |> List.map (fun f -> "        " + f) |> String.concat ",\n") + ");")
        | None -> ()

    for u in seam.Unions do
        line ""

        let made (c: CaseView) (from: string) =
            $"""new {c.Name}({c.Fields |> Seq.map (fun f -> f.Cross.Out $"{from}.{id' f.Member}") |> String.concat ", "})"""

        match List.ofSeq u.Cases with
        | [ only ] when only.DomainCase = "" -> line $"""    public static {u.Name} View(this {u.Domain} value) => {made only "value"};"""
        | _ ->
            line $"    public static {u.Name} View(this {u.Domain} value) => value switch"
            line "    {"

            for c in u.Cases do
                match c.Cast with
                | None -> line $"""        {{ Tag: {c.DomainCase} }} => {made c "value"},"""
                | Some cast -> line $"""        {cast} x => {made c "x"},"""

            line $"        _ => throw new InvalidOperationException($\"{{value}} is no case of {u.Display} the seam was written for: build again.\"),"
            line "    };"

    for r in seam.Refusals do
        line ""
        line $"    /// {r.Display} as Refused: its case's name, and its own Message."

        match r.Codes with
        | [ only ] -> line $"    public static Refused Refusal(this {r.Domain} refusal) => new(\"{only}\", refusal.Message);"
        | codes ->
            line $"    public static Refused Refusal(this {r.Domain} refusal) => new("
            line "        refusal.Tag switch"
            line "        {"

            for code in codes do
                line $"            {r.Domain}.Tags.{code} => \"{code}\","

            line $"            _ => throw new InvalidOperationException($\"{{refusal}} is no case of {r.Display} the seam was written for: build again.\"),"
            line "        },"
            line "        refusal.Message);"

    for o in seam.Outcomes do
        line ""
        line $"    public static {o.Cs} View(this {o.Domain} outcome) => outcome switch"
        line "    {"

        for domainCase, cross in o.Arms do
            line $"""        {domainCase} x => new {o.Cs}({cross.Out "x"}),"""

        line "    };"

    line "}"
    short (text.ToString())

// ---- a data type ----

let signature (m: Member) (lockForm: bool) (isAsync: bool) =
    let t =
        match m.Returns with
        | Nothing -> "void"
        | Task -> "Task"
        | TaskOf -> $"Task<{m.Result.Value.CsFull}>"
        | ValueTaskOf -> $"ValueTask<{m.Result.Value.CsFull}>"
        | Value -> m.Result.Value.CsFull

    let generic = if m.TypeParameters.IsEmpty then "" else $"""<{String.concat ", " m.TypeParameters}>"""
    let head = $"""{(if m.Static then "static " else "")}{(if isAsync then "async " else "")}{t} {m.Name}{generic}"""

    if m.Property then
        head
    else
        let ps = m.Parameters |> List.map (fun (n, c) -> $"{c.CsFull} {id' n}")
        let list = if lockForm then String.concat ", " ps else parameters ps "    "
        $"{head}({list}){m.Constraints}"

let private dataFile (seam: SeamModel) (data: DataClass) =
    let text =
        StringBuilder(
            start
                seam
                [ "System"
                  "System.Threading"
                  "System.Threading.Tasks"
                  "Microsoft.FSharp.Collections"
                  "Microsoft.FSharp.Core"
                  "Plasm.CSharp" ]
        )

    let line (s: string) = text.Append(s).Append('\n') |> ignore
    line ""

    summary
        seam
        line
        ""
        $"T:{data.Display}"
        [ $"What the host calls: every public member of the F# type {data.Display},"
          "taking plain arguments and answering views." ]

    line $"public sealed class {data.Name}({data.Domain} inner)"
    line "{"
    line "    /// The F# object this one calls."
    line $"    public {data.Domain} Inner => inner;"

    for m in data.Members do
        line ""
        summary seam line "    " (memberDoc seam data.Display m) []
        let target = if m.Static then data.Domain else "inner"

        if m.Property then
            line $"""    public {signature m false false} => {m.Result.Value.Out $"{target}.{m.Name}"};"""
        else
            let generic = if m.TypeParameters.IsEmpty then "" else $"""<{String.concat ", " m.TypeParameters}>"""

            let call =
                $"""{target}.{m.Name}{generic}({m.Parameters |> List.map (fun (n, c) -> c.In.Value(id' n)) |> String.concat ", "})"""

            let awaited =
                (m.Returns = TaskOf || m.Returns = ValueTaskOf)
                && not m.Result.Value.Identity

            let body =
                match m.Result with
                | None -> call
                | Some r when r.Identity -> call
                | Some r when awaited -> (r.Out $"(await {call})").Replace($"((await {call}))", $"(await {call})")
                | Some r -> r.Out call

            line $"    public {signature m false awaited} =>"
            line $"        {body};"

    line "}"
    short (text.ToString())

// ---- JSON ----

let private jsonFile (seam: SeamModel) =
    let text = StringBuilder(start seam [ "System.Text.Json"; "System.Text.Json.Serialization"; "Plasm.CSharp" ])
    let line (s: string) = text.Append(s).Append('\n') |> ignore

    line
        """
/// The JSON of every view, every outcome case and the host types Seam.cs lists
/// with SeamJson, made by System.Text.Json's own generator (so it works in a
/// native binary). Put it first in the host's chain:
/// options.SerializerOptions.TypeInfoResolverChain.Insert(0, SeamJson.Default).
[JsonSourceGenerationOptions(JsonSerializerDefaults.Web, RespectNullableAnnotations = true, RespectRequiredConstructorParameters = true)]"""

    for t in Seq.append seam.Json seam.HostJson do
        line $"[JsonSerializable(typeof({t}))]"

    line "internal partial class SeamJson : JsonSerializerContext;"
    short (text.ToString())

// ---- HTTP ----

let status (shape: OutcomeShape) (case: string option * string) : (string * int) option =
    match case with
    | None, _ when shape.Name = "AddResult" -> Some("Results.Created(location(x), x)", 201)
    | None, _ -> Some("Results.Ok(x)", 200)
    | Some _, "Missing" -> Some("Results.NotFound(x)", 404)
    | Some _, "Invalid" -> Some("Results.BadRequest(x)", 400)
    | Some _, "Refused" -> Some("Results.UnprocessableEntity(x)", 422)
    | Some _, "Stale" -> Some("Results.Conflict(x)", 409)
    | _ -> None

let hasHttp (shape: OutcomeShape) =
    (shape.Cases |> List.filter (fun (cs, _) -> cs.IsNone) |> List.length) = 1
    && shape.Cases |> List.forall (fun c -> (status shape c).IsSome)

let private httpFile (seam: SeamModel) =
    let text = StringBuilder(start seam [ "System"; "System.Threading.Tasks"; "Microsoft.AspNetCore.Http"; "Plasm.CSharp" ])
    let line (s: string) = text.Append(s).Append('\n') |> ignore

    line
        """
/// Each Plasm outcome as its HTTP result, so an endpoint is one line:
/// app.MapGet("/things/{id:guid}", (Guid id, Things d, CancellationToken ct) => d.ThingAsync(id, ct).ToHttp());
public static class SeamHttp
{"""

    let mutable first = true

    for shape in seam.Shapes |> Seq.filter hasHttp do
        if not first then line ""
        first <- false
        let created = shape.Name = "AddResult"
        let extra = if created then ", Func<T, string> location" else ""
        let pass = if created then "location" else ""

        let says =
            shape.Cases
            |> List.map (fun ((cs, n) as c) -> $"""{(if cs.IsNone then "its value" else n)} {snd (status shape c).Value}""")
            |> String.concat ", "

        let urlNote = if created then " `location` is the new value's URL." else ""
        line $"    /// {shape.Name}: {says}.{urlNote}"
        line $"    public static IResult ToHttp<T>(this {shape.Cs}<T> outcome{extra}) where T : notnull => outcome switch"
        line "    {"

        for (cs, _) as c in shape.Cases do
            line $"""        {cs |> Option.defaultValue "T"} x => {fst (status shape c).Value},"""

        line "    };"
        line ""
        line $"    public static async Task<IResult> ToHttp<T>(this Task<{shape.Cs}<T>> outcome{extra}) where T : notnull =>"
        line $"        (await outcome).ToHttp({pass});"

    line "}"
    short (text.ToString())

/// Every file the seam writes, by name.
let files (seam: SeamModel) (http: bool) : (string * string) list =
    // The data classes first: writing a parameter marks the records it takes,
    // whose mapping back SeamMap then writes.
    let data = [ for d in seam.Data -> d.Name + ".g.cs", dataFile seam d ]

    [ "Views.g.cs", viewsFile seam
      "SeamMap.g.cs", mapFile seam
      "SeamJson.g.cs", jsonFile seam
      yield! data
      if http && seam.Shapes.Count > 0 then
          "SeamHttp.g.cs", httpFile seam ]
